import{_ as e,o as i,c as a,aB as d}from"./chunks/framework.Mr56icos.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md","lastUpdated":null}'),l={name:"configuration.md"};function r(s,t,o,n,g,h){return i(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="Configuration" tabindex="-1">Configuration <a class="header-anchor" href="#Configuration" aria-label="Permalink to &quot;Configuration {#Configuration}&quot;">​</a></h1><p>Lazy.jl uses TOML parameter files with four sections. Generate an annotated example with <code>lazy params &gt; example.toml</code>.</p><h2 id="io-–-Input/Output" tabindex="-1"><code>[io]</code> – Input/Output <a class="header-anchor" href="#io-–-Input/Output" aria-label="Permalink to &quot;`[io]` – Input/Output {#io-–-Input/Output}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>input_catalog</code></td><td style="text-align:right;">String</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Path to input FITS catalog</td></tr><tr><td style="text-align:right;"><code>output_file</code></td><td style="text-align:right;">String</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Output file path (<code>.fits</code>, <code>.h5</code>, or <code>.hdf5</code>)</td></tr><tr><td style="text-align:right;"><code>output_format</code></td><td style="text-align:right;">String</td><td style="text-align:right;">inferred</td><td style="text-align:right;">Output format: <code>&#39;fits&#39;</code>, <code>&#39;hdf5&#39;</code>, or <code>&#39;both&#39;</code>. If omitted, inferred from <code>output_file</code> extension</td></tr><tr><td style="text-align:right;"><code>missing_data_format</code></td><td style="text-align:right;">String</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">How missing data is encoded in the catalog: <code>&#39;nan&#39;</code>, <code>&#39;zero&#39;</code>, or a numeric value (e.g., <code>&#39;-99&#39;</code>)</td></tr><tr><td style="text-align:right;"><code>output_pz</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Include P(z) distributions in output</td></tr><tr><td style="text-align:right;"><code>output_templates</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Include IGM-attenuated template SEDs in output (needed for SED reconstruction)</td></tr></tbody></table><h3 id="Rest-Frame-Magnitudes" tabindex="-1">Rest-Frame Magnitudes <a class="header-anchor" href="#Rest-Frame-Magnitudes" aria-label="Permalink to &quot;Rest-Frame Magnitudes {#Rest-Frame-Magnitudes}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>output_restframe_mags</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Compute rest-frame absolute magnitudes (M_UV, M_U, M_V, M_J)</td></tr><tr><td style="text-align:right;"><code>flux_units</code></td><td style="text-align:right;">String</td><td style="text-align:right;">–</td><td style="text-align:right;"><strong>Required if <code>output_restframe_mags = true</code></strong>. Flux units of the input catalog: <code>&#39;uJy&#39;</code>, <code>&#39;nJy&#39;</code>, <code>&#39;Jy&#39;</code>, or <code>&#39;cgs&#39;</code></td></tr><tr><td style="text-align:right;"><code>H0</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>70.0</code></td><td style="text-align:right;">Hubble constant in km/s/Mpc (flat LCDM cosmology)</td></tr><tr><td style="text-align:right;"><code>Om</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>0.3</code></td><td style="text-align:right;">Matter density parameter (flat LCDM cosmology)</td></tr></tbody></table><h3 id="Forced-Low-Redshift-Fitting" tabindex="-1">Forced Low-Redshift Fitting <a class="header-anchor" href="#Forced-Low-Redshift-Fitting" aria-label="Permalink to &quot;Forced Low-Redshift Fitting {#Forced-Low-Redshift-Fitting}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>output_forced_lowz</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Perform a second fit restricted to low redshifts</td></tr><tr><td style="text-align:right;"><code>forced_lowz_zmax</code></td><td style="text-align:right;">Float</td><td style="text-align:right;">–</td><td style="text-align:right;"><strong>Required if <code>output_forced_lowz = true</code></strong>. Maximum redshift for the forced low-z fit</td></tr></tbody></table><p>When enabled, the output includes <code>z_best_lowz</code>, <code>chi2_lowz</code>, <code>delta_chi2</code> (= chi2_lowz - chi2_best), low-z P(z) quantiles, and low-z model photometry. This is useful for validating high-redshift candidates.</p><h2 id="fitting-–-Scientific-Parameters" tabindex="-1"><code>[fitting]</code> – Scientific Parameters <a class="header-anchor" href="#fitting-–-Scientific-Parameters" aria-label="Permalink to &quot;`[fitting]` – Scientific Parameters {#fitting-–-Scientific-Parameters}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>template_set</code></td><td style="text-align:right;">String or Array</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Template set name (e.g., <code>&#39;sfhz&#39;</code>) or list of custom template file paths</td></tr><tr><td style="text-align:right;"><code>template_error</code></td><td style="text-align:right;">String</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Template error model. Currently only <code>&#39;template_error&#39;</code> is supported</td></tr><tr><td style="text-align:right;"><code>template_error_scale</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Scale factor for the template error function</td></tr><tr><td style="text-align:right;"><code>igm_model</code></td><td style="text-align:right;">String</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">IGM attenuation model. Currently only <code>&#39;inoue14&#39;</code> is supported</td></tr><tr><td style="text-align:right;"><code>nphot_min</code></td><td style="text-align:right;">Int</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Minimum number of valid photometric points (SNR &gt; 2) required to run the fit</td></tr><tr><td style="text-align:right;"><code>sys_err</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Systematic error added in quadrature to photometric errors</td></tr><tr><td style="text-align:right;"><code>z_min</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Minimum redshift for the fitting grid</td></tr><tr><td style="text-align:right;"><code>z_max</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Maximum redshift for the fitting grid</td></tr><tr><td style="text-align:right;"><code>z_step</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><em>required</em></td><td style="text-align:right;">Redshift step size</td></tr><tr><td style="text-align:right;"><code>template_cache</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>true</code></td><td style="text-align:right;">Cache template grids for reuse in subsequent runs</td></tr></tbody></table><h3 id="Spectroscopic-Redshifts" tabindex="-1">Spectroscopic Redshifts <a class="header-anchor" href="#Spectroscopic-Redshifts" aria-label="Permalink to &quot;Spectroscopic Redshifts {#Spectroscopic-Redshifts}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>use_zspec</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Fix the fit at the spectroscopic redshift when available</td></tr></tbody></table><p>When enabled, objects with a valid spectroscopic redshift (not NaN, not negative) are fit only at the nearest grid point to their z_spec. Objects without z_spec are fit normally across the full grid. Requires a <code>zspec</code> entry in the <code>[translate]</code> section.</p><h3 id="CGM-Damping-Wing" tabindex="-1">CGM Damping Wing <a class="header-anchor" href="#CGM-Damping-Wing" aria-label="Permalink to &quot;CGM Damping Wing {#CGM-Damping-Wing}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>add_cgm</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>true</code></td><td style="text-align:right;">Enable CGM Lyman-alpha damping wing absorption (Asada+2024)</td></tr><tr><td style="text-align:right;"><code>cgm_A</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>3.5918</code></td><td style="text-align:right;">Sigmoid amplitude for HI column density evolution</td></tr><tr><td style="text-align:right;"><code>cgm_a</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>1.8414</code></td><td style="text-align:right;">Sigmoid slope for HI column density evolution</td></tr><tr><td style="text-align:right;"><code>cgm_c</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>18.001</code></td><td style="text-align:right;">Sigmoid baseline for log10(N_HI)</td></tr></tbody></table><p>The CGM model adds damping wing absorption redward of Lyman-alpha at z &gt;= 6, applied multiplicatively on top of the IGM attenuation. The HI column density evolves with redshift as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log10(N_HI) = A / (1 + exp(-a * (z - 6))) + c</span></span></code></pre></div><p>The default parameters are from Asada et al. (2024) and generally do not need to be changed.</p><h2 id="runtime-–-Processing-Options" tabindex="-1"><code>[runtime]</code> – Processing Options <a class="header-anchor" href="#runtime-–-Processing-Options" aria-label="Permalink to &quot;`[runtime]` – Processing Options {#runtime-–-Processing-Options}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>chunked_processing</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Enable memory-efficient chunked processing</td></tr><tr><td style="text-align:right;"><code>target_memory_gb</code></td><td style="text-align:right;">Float</td><td style="text-align:right;"><code>0.5</code></td><td style="text-align:right;">Target memory usage per chunk in GB</td></tr><tr><td style="text-align:right;"><code>preserve_work_file</code></td><td style="text-align:right;">Bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Keep intermediate <code>.work.h5</code> file after completion</td></tr></tbody></table><p>See <a href="/hollisakins.com/Lazy.jl/previews/PR8/advanced#Advanced-Usage">Advanced Usage</a> for details on chunked processing and resume capability.</p><h2 id="translate-–-Column-Mapping" tabindex="-1"><code>[translate]</code> – Column Mapping <a class="header-anchor" href="#translate-–-Column-Mapping" aria-label="Permalink to &quot;`[translate]` – Column Mapping {#translate-–-Column-Mapping}&quot;">​</a></h2><p>Maps filter names to flux/error columns in your input catalog.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">translate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    f606w = {flux = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;f_f606w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, error = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;e_f606w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    f814w = {flux = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;f_f814w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, error = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;e_f814w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    f115w = {flux = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;f_f115w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, error = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;e_f115w&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The keys are filter names or nicknames (see <a href="/hollisakins.com/Lazy.jl/previews/PR8/filters#Filters">Filters</a> for the full list). The values must match column names in the input FITS catalog.</p><h3 id="Spectroscopic-Redshift-Column" tabindex="-1">Spectroscopic Redshift Column <a class="header-anchor" href="#Spectroscopic-Redshift-Column" aria-label="Permalink to &quot;Spectroscopic Redshift Column {#Spectroscopic-Redshift-Column}&quot;">​</a></h3><p>When <code>use_zspec = true</code> in <code>[fitting]</code>, add a <code>zspec</code> entry:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">translate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    zspec = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;z_spec&#39;</span></span></code></pre></div><p>This maps to the column containing spectroscopic redshifts. Objects with NaN, negative, or missing values are fit normally.</p>',30)])])}const y=e(l,[["render",r]]);export{p as __pageData,y as default};
